# Generated by manage.py generate_test_cases.
from importlib import import_module

from django.apps import apps
from django.contrib.auth import get_user_model
from django.contrib.auth.models import Group
from django.db import connection
from django.db.migrations.state import ProjectState

from bloomerp.models.communication.inbox.inbox import Inbox
from bloomerp.models.communication.inbox.inbox_folder import InboxFolder
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ModelScenario,
)


class TestInboxModel(BloomerpModelTestCase):
    model = Inbox

    def get_test_scenarios(self) -> list[ModelScenario[Inbox]]:
        """Return lifecycle scenarios; migration coverage uses historical models below."""
        return []

    def test_messaging_folder_backfill(self) -> None:
        """Backfill personal inboxes idempotently without changing shared preferences."""
        owner = get_user_model().objects.create(username="inbox_owner")
        other = get_user_model().objects.create(username="inbox_other")
        personal = Inbox.objects.create(user=owner, name="Existing personal")
        existing = Inbox.objects.create(user=owner, name="Already migrated")
        folder = InboxFolder.objects.create(inbox=existing, type="instant_messaging")
        reference = Inbox.objects.create(
            user=other, source_object=personal, name="Reference"
        )
        shared_user = Inbox.objects.create(user=owner, name="Shared user")
        shared_user.shared_with_users.add(other)
        shared_group = Inbox.objects.create(user=owner, name="Shared group")
        shared_group.shared_with_groups.add(Group.objects.create(name="Inbox audience"))
        initial = Inbox.objects.create(
            user=owner, name="Initial default", initial_default=True
        )

        migration = import_module(
            "bloomerp.migrations.0090_backfill_instant_messaging_folders"
        )
        state = ProjectState.from_apps(apps)
        operation = migration.Migration.operations[0]
        for _ in range(2):
            operation.database_forwards(
                "bloomerp", connection.schema_editor(), state, state
            )

        self.assertEqual(
            InboxFolder.objects.filter(
                inbox=personal, type="instant_messaging"
            ).count(),
            1,
        )
        self.assertEqual(
            list(
                InboxFolder.objects.filter(inbox=existing).values_list("pk", flat=True)
            ),
            [folder.pk],
        )
        self.assertFalse(
            InboxFolder.objects.filter(
                inbox__in=[reference, shared_user, shared_group],
                type="instant_messaging",
            ).exists()
        )
        self.assertEqual(
            InboxFolder.objects.filter(inbox=initial, type="instant_messaging").count(),
            1,
        )
        operation.database_backwards(
            "bloomerp", connection.schema_editor(), state, state
        )
        self.assertTrue(InboxFolder.objects.filter(pk=folder.pk).exists())
        self.assertTrue(
            InboxFolder.objects.filter(
                inbox=personal, type="instant_messaging"
            ).exists()
        )
